window.MG_LAZY_DATA["data/lazy/owner-courses/a033-5d3eaa6418642d86.json"]={sha256:"5d3eaa6418642d8653c8f9c3599192bc4fc87008adeed905fa81713b10451850",value:{"id":"a033","title":"化學放大型光阻設計","titleEn":"Chemically amplified resist design","category":"semiconductor","kind":"course","summary":"以 4 階段、24 個工程工作包拆解PAG、淬熄、反應擴散與隨機性，完成圖解、對照、敏感度分析、故障判別、量測規劃與驗收。","summaryEn":"Four stages and 24 work packages explore pag, quenching, reaction-diffusion and stochasticity through diagrams, comparisons, sensitivity studies, fault diagnosis, measurement plans and acceptance reviews.","sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop","v3-media-80679a241086"],"status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":720,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"scope":"依公開原理編寫的雙語概念實作課；每步交付可審查的工程證據。24 步是學習拆解，不代表晶圓廠的完整配方。自行設定的數值須標為假設。題目不含可直接操作的化學混配、設備設定或量產公差；照片與外部影片為代表媒體，不是假稱每步實拍。","scopeEn":"Bilingual conceptual exercises based on public principles, with reviewable evidence at each step. The 24 steps are a learning decomposition, not a complete fab recipe. Chosen numerical inputs must be labeled hypothetical. No directly operable chemical mixtures, equipment settings or production tolerances are supplied. Photos and external videos are representative media, not claimed as recordings of every step.","diagram":{"type":"wafer","labels":["配方功能分工","光化學及擴散","圖案與隨機性","整合及材料評估"],"labelsEn":["Formulation functions","Photochemistry and diffusion","Patterning and stochasticity","Integration and material assessment"],"original":true,"notToScale":true},"stages":[{"id":"a033-stage01","order":1,"title":"配方功能分工","titleEn":"Formulation functions","description":"在「配方功能分工」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for formulation functions, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a033-v8-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":[],"title":"放大機制定義","titleEn":"Define amplification","objective":"完成「放大機制定義」的因果圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for define amplification, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：放大機制定義。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：光生催化劑可啟動多次溶解度改變反應。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define amplification. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: A photogenerated catalyst can initiate multiple solubility-changing reactions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「光生催化劑可啟動多次溶解度改變反應。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A photogenerated catalyst can initiate multiple solubility-changing reactions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「放大機制定義」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for define amplification and add discriminating evidence.","check":"交付「放大機制定義」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for define amplification: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a033-v8-01-k1","title":"放大機制定義的原理","titleEn":"Define amplification principle","text":"光生催化劑可啟動多次溶解度改變反應。","textEn":"A photogenerated catalyst can initiate multiple solubility-changing reactions."},{"id":"a033-v8-01-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「放大機制定義」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define amplification?","options":["光生催化劑可啟動多次溶解度改變反應。","相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["A photogenerated catalyst can initiate multiple solubility-changing reactions.","Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step."],"answer":0,"explanation":"光生催化劑可啟動多次溶解度改變反應。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"A photogenerated catalyst can initiate multiple solubility-changing reactions. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}},{"id":"a033-v8-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-01"],"title":"樹脂保護基","titleEn":"Assign protecting groups","objective":"完成「樹脂保護基」的對照表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for assign protecting groups, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：樹脂保護基。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：保護基轉換使樹脂對顯影液的親和改變。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assign protecting groups. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Protecting-group conversion changes resin affinity to developer. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「保護基轉換使樹脂對顯影液的親和改變。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Protecting-group conversion changes resin affinity to developer. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「樹脂保護基」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assign protecting groups and add discriminating evidence.","check":"交付「樹脂保護基」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for assign protecting groups: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a033-v8-02-k1","title":"樹脂保護基的原理","titleEn":"Assign protecting groups principle","text":"保護基轉換使樹脂對顯影液的親和改變。","textEn":"Protecting-group conversion changes resin affinity to developer."},{"id":"a033-v8-02-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「樹脂保護基」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assign protecting groups?","options":["相同最終轉速一定得到相同膜厚分布。","保護基轉換使樹脂對顯影液的親和改變。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Protecting-group conversion changes resin affinity to developer.","Softbake and PEB are the same chemical step."],"answer":1,"explanation":"保護基轉換使樹脂對顯影液的親和改變。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"Protecting-group conversion changes resin affinity to developer. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}},{"id":"a033-v8-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-02"],"title":"光酸產生劑","titleEn":"Assign photoacid generators","objective":"完成「光酸產生劑」的敏感度草圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assign photoacid generators, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：光酸產生劑。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：PAG 吸收、產酸與相容性須同時評估。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assign photoacid generators. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: PAG absorption, acid generation and compatibility need joint evaluation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「PAG 吸收、產酸與相容性須同時評估。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: PAG absorption, acid generation and compatibility need joint evaluation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「光酸產生劑」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assign photoacid generators and add discriminating evidence.","check":"交付「光酸產生劑」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assign photoacid generators: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a033-v8-03-k1","title":"光酸產生劑的原理","titleEn":"Assign photoacid generators principle","text":"PAG 吸收、產酸與相容性須同時評估。","textEn":"PAG absorption, acid generation and compatibility need joint evaluation."},{"id":"a033-v8-03-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「光酸產生劑」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assign photoacid generators?","options":["相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。","PAG 吸收、產酸與相容性須同時評估。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step.","PAG absorption, acid generation and compatibility need joint evaluation."],"answer":2,"explanation":"PAG 吸收、產酸與相容性須同時評估。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"PAG absorption, acid generation and compatibility need joint evaluation. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}},{"id":"a033-v8-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-03"],"title":"淬熄劑作用","titleEn":"Assign quencher functions","objective":"完成「淬熄劑作用」的故障判別表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for assign quencher functions, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：淬熄劑作用。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：淬熄劑限制酸反應也可能降低感度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assign quencher functions. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Quenchers limit acid activity but can reduce sensitivity. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「淬熄劑限制酸反應也可能降低感度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Quenchers limit acid activity but can reduce sensitivity. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「淬熄劑作用」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assign quencher functions and add discriminating evidence.","check":"交付「淬熄劑作用」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for assign quencher functions: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a033-v8-04-k1","title":"淬熄劑作用的原理","titleEn":"Assign quencher functions principle","text":"淬熄劑限制酸反應也可能降低感度。","textEn":"Quenchers limit acid activity but can reduce sensitivity."},{"id":"a033-v8-04-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「淬熄劑作用」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assign quencher functions?","options":["淬熄劑限制酸反應也可能降低感度。","相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Quenchers limit acid activity but can reduce sensitivity.","Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step."],"answer":0,"explanation":"淬熄劑限制酸反應也可能降低感度。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"Quenchers limit acid activity but can reduce sensitivity. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}},{"id":"a033-v8-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-04"],"title":"溶劑與成膜","titleEn":"Choose film-formation evidence","objective":"完成「溶劑與成膜」的量測規劃，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for choose film-formation evidence, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：溶劑與成膜。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：溶液均勻不保證乾膜成分分布均勻。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Choose film-formation evidence. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: A uniform solution does not guarantee uniform dry-film composition. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「溶液均勻不保證乾膜成分分布均勻。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A uniform solution does not guarantee uniform dry-film composition. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「溶劑與成膜」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for choose film-formation evidence and add discriminating evidence.","check":"交付「溶劑與成膜」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for choose film-formation evidence: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a033-v8-05-k1","title":"溶劑與成膜的原理","titleEn":"Choose film-formation evidence principle","text":"溶液均勻不保證乾膜成分分布均勻。","textEn":"A uniform solution does not guarantee uniform dry-film composition."},{"id":"a033-v8-05-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「溶劑與成膜」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating choose film-formation evidence?","options":["相同最終轉速一定得到相同膜厚分布。","溶液均勻不保證乾膜成分分布均勻。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","A uniform solution does not guarantee uniform dry-film composition.","Softbake and PEB are the same chemical step."],"answer":1,"explanation":"溶液均勻不保證乾膜成分分布均勻。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"A uniform solution does not guarantee uniform dry-film composition. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}},{"id":"a033-v8-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-05"],"title":"波長相容","titleEn":"Assess wavelength compatibility","objective":"完成「波長相容」的工程驗收單，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for assess wavelength compatibility, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：波長相容。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：材料吸收需配合目標曝光波長與膜厚。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess wavelength compatibility. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Absorption must match exposure wavelength and film thickness. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「材料吸收需配合目標曝光波長與膜厚。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Absorption must match exposure wavelength and film thickness. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「波長相容」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assess wavelength compatibility and add discriminating evidence.","check":"交付「波長相容」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for assess wavelength compatibility: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a033-v8-06-k1","title":"波長相容的原理","titleEn":"Assess wavelength compatibility principle","text":"材料吸收需配合目標曝光波長與膜厚。","textEn":"Absorption must match exposure wavelength and film thickness."},{"id":"a033-v8-06-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","textEn":"Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}],"quiz":{"question":"評估「波長相容」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess wavelength compatibility?","options":["相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。","材料吸收需配合目標曝光波長與膜厚。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step.","Absorption must match exposure wavelength and film thickness."],"answer":2,"explanation":"材料吸收需配合目標曝光波長與膜厚。 化學放大將光吸收與多次催化轉換連起來，但產酸效率、淬熄及溶解反應決定有效增益。","explanationEn":"Absorption must match exposure wavelength and film thickness. Chemical amplification links absorption to multiple catalytic conversions, while acid yield, quenching and dissolution set effective gain."}}]},{"id":"a033-stage02","order":2,"title":"光化學及擴散","titleEn":"Photochemistry and diffusion","description":"在「光化學及擴散」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for photochemistry and diffusion, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a033-v8-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-06"],"title":"吸收深度","titleEn":"Estimate absorption depth","objective":"完成「吸收深度」的因果圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for estimate absorption depth, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：吸收深度。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：過強吸收可能造成上下層反應不均。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Estimate absorption depth. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Excessive absorption can produce through-film reaction gradients. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「過強吸收可能造成上下層反應不均。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Excessive absorption can produce through-film reaction gradients. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「吸收深度」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for estimate absorption depth and add discriminating evidence.","check":"交付「吸收深度」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for estimate absorption depth: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a033-v8-07-k1","title":"吸收深度的原理","titleEn":"Estimate absorption depth principle","text":"過強吸收可能造成上下層反應不均。","textEn":"Excessive absorption can produce through-film reaction gradients."},{"id":"a033-v8-07-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「吸收深度」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating estimate absorption depth?","options":["過強吸收可能造成上下層反應不均。","曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Excessive absorption can produce through-film reaction gradients.","Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum."],"answer":0,"explanation":"過強吸收可能造成上下層反應不均。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Excessive absorption can produce through-film reaction gradients. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}},{"id":"a033-v8-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-07"],"title":"酸產生統計","titleEn":"Assess acid-generation statistics","objective":"完成「酸產生統計」的對照表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for assess acid-generation statistics, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：酸產生統計。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：微小區域的光子與分子事件具有隨機性。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess acid-generation statistics. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Photon and molecular events are stochastic in small volumes. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「微小區域的光子與分子事件具有隨機性。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Photon and molecular events are stochastic in small volumes. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「酸產生統計」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for assess acid-generation statistics and add discriminating evidence.","check":"交付「酸產生統計」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for assess acid-generation statistics: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a033-v8-08-k1","title":"酸產生統計的原理","titleEn":"Assess acid-generation statistics principle","text":"微小區域的光子與分子事件具有隨機性。","textEn":"Photon and molecular events are stochastic in small volumes."},{"id":"a033-v8-08-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「酸產生統計」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess acid-generation statistics?","options":["曝光劑量相同就能排除所有尺寸差。","微小區域的光子與分子事件具有隨機性。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Equal dose rules out every dimensional difference.","Photon and molecular events are stochastic in small volumes.","A top-view opening proves no bottom scum."],"answer":1,"explanation":"微小區域的光子與分子事件具有隨機性。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Photon and molecular events are stochastic in small volumes. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}},{"id":"a033-v8-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-08"],"title":"反應與擴散","titleEn":"Separate reaction and diffusion","objective":"完成「反應與擴散」的敏感度草圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for separate reaction and diffusion, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：反應與擴散。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：反應速率與擴散係數控制不同影像特徵。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate reaction and diffusion. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Reaction rate and diffusivity control different image characteristics. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「反應速率與擴散係數控制不同影像特徵。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Reaction rate and diffusivity control different image characteristics. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「反應與擴散」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for separate reaction and diffusion and add discriminating evidence.","check":"交付「反應與擴散」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for separate reaction and diffusion: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a033-v8-09-k1","title":"反應與擴散的原理","titleEn":"Separate reaction and diffusion principle","text":"反應速率與擴散係數控制不同影像特徵。","textEn":"Reaction rate and diffusivity control different image characteristics."},{"id":"a033-v8-09-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「反應與擴散」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate reaction and diffusion?","options":["曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。","反應速率與擴散係數控制不同影像特徵。"],"optionsEn":["Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum.","Reaction rate and diffusivity control different image characteristics."],"answer":2,"explanation":"反應速率與擴散係數控制不同影像特徵。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Reaction rate and diffusivity control different image characteristics. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}},{"id":"a033-v8-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-09"],"title":"PEB 敏感度","titleEn":"Measure PEB sensitivity","objective":"完成「PEB 敏感度」的故障判別表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for measure peb sensitivity, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：PEB 敏感度。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：高溫敏感度可能放大熱板不均造成的尺寸差。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure PEB sensitivity. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Strong temperature sensitivity can amplify hotplate-related CD variation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高溫敏感度可能放大熱板不均造成的尺寸差。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Strong temperature sensitivity can amplify hotplate-related CD variation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「PEB 敏感度」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for measure peb sensitivity and add discriminating evidence.","check":"交付「PEB 敏感度」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for measure peb sensitivity: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a033-v8-10-k1","title":"PEB 敏感度的原理","titleEn":"Measure PEB sensitivity principle","text":"高溫敏感度可能放大熱板不均造成的尺寸差。","textEn":"Strong temperature sensitivity can amplify hotplate-related CD variation."},{"id":"a033-v8-10-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「PEB 敏感度」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure peb sensitivity?","options":["高溫敏感度可能放大熱板不均造成的尺寸差。","曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Strong temperature sensitivity can amplify hotplate-related CD variation.","Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum."],"answer":0,"explanation":"高溫敏感度可能放大熱板不均造成的尺寸差。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Strong temperature sensitivity can amplify hotplate-related CD variation. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}},{"id":"a033-v8-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-10"],"title":"酸中和競爭","titleEn":"Analyze acid-neutralization competition","objective":"完成「酸中和競爭」的量測規劃，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for analyze acid-neutralization competition, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：酸中和競爭。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：淬熄與去保護反應競爭決定有效反應範圍。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Analyze acid-neutralization competition. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Quenching competes with deprotection to set the effective reaction region. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「淬熄與去保護反應競爭決定有效反應範圍。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Quenching competes with deprotection to set the effective reaction region. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「酸中和競爭」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for analyze acid-neutralization competition and add discriminating evidence.","check":"交付「酸中和競爭」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for analyze acid-neutralization competition: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a033-v8-11-k1","title":"酸中和競爭的原理","titleEn":"Analyze acid-neutralization competition principle","text":"淬熄與去保護反應競爭決定有效反應範圍。","textEn":"Quenching competes with deprotection to set the effective reaction region."},{"id":"a033-v8-11-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「酸中和競爭」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating analyze acid-neutralization competition?","options":["曝光劑量相同就能排除所有尺寸差。","淬熄與去保護反應競爭決定有效反應範圍。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Equal dose rules out every dimensional difference.","Quenching competes with deprotection to set the effective reaction region.","A top-view opening proves no bottom scum."],"answer":1,"explanation":"淬熄與去保護反應競爭決定有效反應範圍。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Quenching competes with deprotection to set the effective reaction region. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}},{"id":"a033-v8-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-11"],"title":"自由體積影響","titleEn":"Assess free-volume effects","objective":"完成「自由體積影響」的工程驗收單，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for assess free-volume effects, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：自由體積影響。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：材料狀態會影響分子擴散而非只有溫度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess free-volume effects. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Material state influences molecular diffusion beyond temperature alone. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「材料狀態會影響分子擴散而非只有溫度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Material state influences molecular diffusion beyond temperature alone. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「自由體積影響」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for assess free-volume effects and add discriminating evidence.","check":"交付「自由體積影響」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for assess free-volume effects: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a033-v8-12-k1","title":"自由體積影響的原理","titleEn":"Assess free-volume effects principle","text":"材料狀態會影響分子擴散而非只有溫度。","textEn":"Material state influences molecular diffusion beyond temperature alone."},{"id":"a033-v8-12-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","textEn":"Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}],"quiz":{"question":"評估「自由體積影響」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess free-volume effects?","options":["曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。","材料狀態會影響分子擴散而非只有溫度。"],"optionsEn":["Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum.","Material state influences molecular diffusion beyond temperature alone."],"answer":2,"explanation":"材料狀態會影響分子擴散而非只有溫度。 擴散長度與反應速率是不同參數，藉獨立圖案或時間實驗才能避免把反應加快誤判為酸移動更遠。","explanationEn":"Material state influences molecular diffusion beyond temperature alone. Diffusion length and reaction rate are different parameters; independent spatial or time experiments avoid confusing faster reaction with farther transport."}}]},{"id":"a033-stage03","order":3,"title":"圖案與隨機性","titleEn":"Patterning and stochasticity","description":"在「圖案與隨機性」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for patterning and stochasticity, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a033-v8-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-12"],"title":"感度解析度粗糙度","titleEn":"Compare sensitivity-resolution-roughness","objective":"完成「感度解析度粗糙度」的因果圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for compare sensitivity-resolution-roughness, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：感度解析度粗糙度。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：降低曝光劑量不保證同時提升解析度與粗糙度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。 以理想 Poisson 事件模型比較平均事件數 100 與 25 的相對波動 1/√N；說明這是光子統計類比，不能直接當成實際缺陷率。","instructionEn":"Question for this step: Compare sensitivity-resolution-roughness. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Lower dose does not guarantee better resolution and roughness together. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs. Use an ideal Poisson model to compare relative fluctuation 1/√N for mean counts 100 and 25. Explain that this photon-statistics analogy is not an actual defect-rate prediction.","observation":"檢查結果是否能支持「降低曝光劑量不保證同時提升解析度與粗糙度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Lower dose does not guarantee better resolution and roughness together. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「感度解析度粗糙度」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for compare sensitivity-resolution-roughness and add discriminating evidence.","check":"交付「感度解析度粗糙度」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。 同時交付算例的中間步驟或比較圖，並標示假設與模型限制。","checkEn":"Submit the causal diagram for compare sensitivity-resolution-roughness: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine. Also submit intermediate calculations or comparison diagrams with assumptions and model limits.","knowledge":[{"id":"a033-v8-13-k1","title":"感度解析度粗糙度的原理","titleEn":"Compare sensitivity-resolution-roughness principle","text":"降低曝光劑量不保證同時提升解析度與粗糙度。","textEn":"Lower dose does not guarantee better resolution and roughness together."},{"id":"a033-v8-13-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「感度解析度粗糙度」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare sensitivity-resolution-roughness?","options":["降低曝光劑量不保證同時提升解析度與粗糙度。","較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Lower dose does not guarantee better resolution and roughness together.","Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":0,"explanation":"降低曝光劑量不保證同時提升解析度與粗糙度。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Lower dose does not guarantee better resolution and roughness together. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}},{"id":"a033-v8-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-13"],"title":"溶解對比","titleEn":"Measure dissolution contrast","objective":"完成「溶解對比」的對照表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for measure dissolution contrast, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：溶解對比。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：去保護比例與實際溶解速率需以資料連結。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure dissolution contrast. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Deprotection fraction needs empirical connection to dissolution rate. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「去保護比例與實際溶解速率需以資料連結。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Deprotection fraction needs empirical connection to dissolution rate. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「溶解對比」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for measure dissolution contrast and add discriminating evidence.","check":"交付「溶解對比」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for measure dissolution contrast: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a033-v8-14-k1","title":"溶解對比的原理","titleEn":"Measure dissolution contrast principle","text":"去保護比例與實際溶解速率需以資料連結。","textEn":"Deprotection fraction needs empirical connection to dissolution rate."},{"id":"a033-v8-14-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「溶解對比」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure dissolution contrast?","options":["較低劑量必定同時改善解析度與粗糙度。","去保護比例與實際溶解速率需以資料連結。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Deprotection fraction needs empirical connection to dissolution rate.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":1,"explanation":"去保護比例與實際溶解速率需以資料連結。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Deprotection fraction needs empirical connection to dissolution rate. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}},{"id":"a033-v8-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-14"],"title":"線邊粗糙","titleEn":"Assess line-edge roughness","objective":"完成「線邊粗糙」的敏感度草圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess line-edge roughness, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：線邊粗糙。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：粗糙度需指定量測長度、濾波及取樣。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess line-edge roughness. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Roughness requires specified evaluation length, filtering and sampling. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「粗糙度需指定量測長度、濾波及取樣。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Roughness requires specified evaluation length, filtering and sampling. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「線邊粗糙」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for assess line-edge roughness and add discriminating evidence.","check":"交付「線邊粗糙」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess line-edge roughness: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a033-v8-15-k1","title":"線邊粗糙的原理","titleEn":"Assess line-edge roughness principle","text":"粗糙度需指定量測長度、濾波及取樣。","textEn":"Roughness requires specified evaluation length, filtering and sampling."},{"id":"a033-v8-15-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「線邊粗糙」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess line-edge roughness?","options":["較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。","粗糙度需指定量測長度、濾波及取樣。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes.","Roughness requires specified evaluation length, filtering and sampling."],"answer":2,"explanation":"粗糙度需指定量測長度、濾波及取樣。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Roughness requires specified evaluation length, filtering and sampling. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}},{"id":"a033-v8-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-15"],"title":"缺孔與橋接","titleEn":"Classify missing and bridged features","objective":"完成「缺孔與橋接」的故障判別表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for classify missing and bridged features, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：缺孔與橋接。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：平均線寬可能掩蓋離散圖案失效。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Classify missing and bridged features. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Mean linewidth can conceal discrete pattern failures. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「平均線寬可能掩蓋離散圖案失效。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Mean linewidth can conceal discrete pattern failures. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「缺孔與橋接」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for classify missing and bridged features and add discriminating evidence.","check":"交付「缺孔與橋接」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for classify missing and bridged features: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a033-v8-16-k1","title":"缺孔與橋接的原理","titleEn":"Classify missing and bridged features principle","text":"平均線寬可能掩蓋離散圖案失效。","textEn":"Mean linewidth can conceal discrete pattern failures."},{"id":"a033-v8-16-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「缺孔與橋接」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating classify missing and bridged features?","options":["平均線寬可能掩蓋離散圖案失效。","較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Mean linewidth can conceal discrete pattern failures.","Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":0,"explanation":"平均線寬可能掩蓋離散圖案失效。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Mean linewidth can conceal discrete pattern failures. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}},{"id":"a033-v8-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-16"],"title":"配方相分離","titleEn":"Inspect phase separation","objective":"完成「配方相分離」的量測規劃，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for inspect phase separation, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：配方相分離。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：添加物分布不均可形成局部反應差異。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Inspect phase separation. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Nonuniform additive distribution can create local reaction differences. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「添加物分布不均可形成局部反應差異。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Nonuniform additive distribution can create local reaction differences. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「配方相分離」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for inspect phase separation and add discriminating evidence.","check":"交付「配方相分離」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for inspect phase separation: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a033-v8-17-k1","title":"配方相分離的原理","titleEn":"Inspect phase separation principle","text":"添加物分布不均可形成局部反應差異。","textEn":"Nonuniform additive distribution can create local reaction differences."},{"id":"a033-v8-17-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「配方相分離」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating inspect phase separation?","options":["較低劑量必定同時改善解析度與粗糙度。","添加物分布不均可形成局部反應差異。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Nonuniform additive distribution can create local reaction differences.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":1,"explanation":"添加物分布不均可形成局部反應差異。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Nonuniform additive distribution can create local reaction differences. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}},{"id":"a033-v8-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-17"],"title":"顯影膨潤","titleEn":"Assess development swelling","objective":"完成「顯影膨潤」的工程驗收單，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for assess development swelling, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：顯影膨潤。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：溶劑進入膜內可能先改變形貌再溶解。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess development swelling. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Solvent ingress can change morphology before dissolution. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「溶劑進入膜內可能先改變形貌再溶解。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Solvent ingress can change morphology before dissolution. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「顯影膨潤」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for assess development swelling and add discriminating evidence.","check":"交付「顯影膨潤」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for assess development swelling: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a033-v8-18-k1","title":"顯影膨潤的原理","titleEn":"Assess development swelling principle","text":"溶劑進入膜內可能先改變形貌再溶解。","textEn":"Solvent ingress can change morphology before dissolution."},{"id":"a033-v8-18-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","textEn":"Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}],"quiz":{"question":"評估「顯影膨潤」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess development swelling?","options":["較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。","溶劑進入膜內可能先改變形貌再溶解。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes.","Solvent ingress can change morphology before dissolution."],"answer":2,"explanation":"溶劑進入膜內可能先改變形貌再溶解。 平均化學反應與少量事件的隨機分布需分開看，低曝光劑量可能增加局部缺陷的不確定度。","explanationEn":"Solvent ingress can change morphology before dissolution. Separate average chemistry from sparse-event statistics; low dose can increase uncertainty in local defect formation."}}]},{"id":"a033-stage04","order":4,"title":"整合及材料評估","titleEn":"Integration and material assessment","description":"在「整合及材料評估」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for integration and material assessment, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a033-v8-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-18"],"title":"蝕刻耐受","titleEn":"Assess etch resistance","objective":"完成「蝕刻耐受」的因果圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for assess etch resistance, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：蝕刻耐受。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：高感度材料仍需要足夠圖案轉移耐受。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess etch resistance. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Sensitive materials still need sufficient pattern-transfer durability. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高感度材料仍需要足夠圖案轉移耐受。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Sensitive materials still need sufficient pattern-transfer durability. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「蝕刻耐受」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for assess etch resistance and add discriminating evidence.","check":"交付「蝕刻耐受」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for assess etch resistance: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a033-v8-19-k1","title":"蝕刻耐受的原理","titleEn":"Assess etch resistance principle","text":"高感度材料仍需要足夠圖案轉移耐受。","textEn":"Sensitive materials still need sufficient pattern-transfer durability."},{"id":"a033-v8-19-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「蝕刻耐受」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess etch resistance?","options":["高感度材料仍需要足夠圖案轉移耐受。","顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Sensitive materials still need sufficient pattern-transfer durability.","Developer compatibility follows directly from color.","More acid diffusion can only improve patterns."],"answer":0,"explanation":"高感度材料仍需要足夠圖案轉移耐受。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Sensitive materials still need sufficient pattern-transfer durability. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}},{"id":"a033-v8-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-19"],"title":"逸氣與殘留","titleEn":"Review outgassing and residue","objective":"完成「逸氣與殘留」的對照表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for review outgassing and residue, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：逸氣與殘留。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：曝光或加熱釋出物可能影響設備與介面。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Review outgassing and residue. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Exposure or thermal outgassing can affect equipment and interfaces. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「曝光或加熱釋出物可能影響設備與介面。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Exposure or thermal outgassing can affect equipment and interfaces. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「逸氣與殘留」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for review outgassing and residue and add discriminating evidence.","check":"交付「逸氣與殘留」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for review outgassing and residue: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a033-v8-20-k1","title":"逸氣與殘留的原理","titleEn":"Review outgassing and residue principle","text":"曝光或加熱釋出物可能影響設備與介面。","textEn":"Exposure or thermal outgassing can affect equipment and interfaces."},{"id":"a033-v8-20-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「逸氣與殘留」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating review outgassing and residue?","options":["顯影液相容性可由顏色直接判斷。","曝光或加熱釋出物可能影響設備與介面。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Developer compatibility follows directly from color.","Exposure or thermal outgassing can affect equipment and interfaces.","More acid diffusion can only improve patterns."],"answer":1,"explanation":"曝光或加熱釋出物可能影響設備與介面。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Exposure or thermal outgassing can affect equipment and interfaces. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}},{"id":"a033-v8-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-20"],"title":"保存與老化","titleEn":"Assess storage aging","objective":"完成「保存與老化」的敏感度草圖，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess storage aging, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：保存與老化。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：配方性能需附批次、儲存條件及使用時點。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess storage aging. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Performance needs lot, storage conditions and time-of-use metadata. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「配方性能需附批次、儲存條件及使用時點。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Performance needs lot, storage conditions and time-of-use metadata. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「保存與老化」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for assess storage aging and add discriminating evidence.","check":"交付「保存與老化」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess storage aging: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a033-v8-21-k1","title":"保存與老化的原理","titleEn":"Assess storage aging principle","text":"配方性能需附批次、儲存條件及使用時點。","textEn":"Performance needs lot, storage conditions and time-of-use metadata."},{"id":"a033-v8-21-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「保存與老化」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess storage aging?","options":["顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。","配方性能需附批次、儲存條件及使用時點。"],"optionsEn":["Developer compatibility follows directly from color.","More acid diffusion can only improve patterns.","Performance needs lot, storage conditions and time-of-use metadata."],"answer":2,"explanation":"配方性能需附批次、儲存條件及使用時點。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Performance needs lot, storage conditions and time-of-use metadata. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}},{"id":"a033-v8-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-21"],"title":"組成實驗設計","titleEn":"Design mixture experiments","objective":"完成「組成實驗設計」的故障判別表，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for design mixture experiments, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：組成實驗設計。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：配方比例互相耦合，不能當作完全獨立變數。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Design mixture experiments. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Composition fractions are coupled rather than fully independent variables. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「配方比例互相耦合，不能當作完全獨立變數。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Composition fractions are coupled rather than fully independent variables. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「組成實驗設計」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for design mixture experiments and add discriminating evidence.","check":"交付「組成實驗設計」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for design mixture experiments: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a033-v8-22-k1","title":"組成實驗設計的原理","titleEn":"Design mixture experiments principle","text":"配方比例互相耦合，不能當作完全獨立變數。","textEn":"Composition fractions are coupled rather than fully independent variables."},{"id":"a033-v8-22-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「組成實驗設計」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating design mixture experiments?","options":["配方比例互相耦合，不能當作完全獨立變數。","顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Composition fractions are coupled rather than fully independent variables.","Developer compatibility follows directly from color.","More acid diffusion can only improve patterns."],"answer":0,"explanation":"配方比例互相耦合，不能當作完全獨立變數。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Composition fractions are coupled rather than fully independent variables. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}},{"id":"a033-v8-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-22"],"title":"資料與配方邊界","titleEn":"Distinguish model from proprietary recipe","objective":"完成「資料與配方邊界」的量測規劃，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for distinguish model from proprietary recipe, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：資料與配方邊界。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：公開原理能支持假說，但不能補出未公開配方。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Distinguish model from proprietary recipe. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Public principles support hypotheses but do not reveal proprietary formulations. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「公開原理能支持假說，但不能補出未公開配方。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Public principles support hypotheses but do not reveal proprietary formulations. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「資料與配方邊界」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for distinguish model from proprietary recipe and add discriminating evidence.","check":"交付「資料與配方邊界」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for distinguish model from proprietary recipe: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a033-v8-23-k1","title":"資料與配方邊界的原理","titleEn":"Distinguish model from proprietary recipe principle","text":"公開原理能支持假說，但不能補出未公開配方。","textEn":"Public principles support hypotheses but do not reveal proprietary formulations."},{"id":"a033-v8-23-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「資料與配方邊界」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating distinguish model from proprietary recipe?","options":["顯影液相容性可由顏色直接判斷。","公開原理能支持假說，但不能補出未公開配方。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Developer compatibility follows directly from color.","Public principles support hypotheses but do not reveal proprietary formulations.","More acid diffusion can only improve patterns."],"answer":1,"explanation":"公開原理能支持假說，但不能補出未公開配方。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Public principles support hypotheses but do not reveal proprietary formulations. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}},{"id":"a033-v8-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-car","v8a-acid","v8a-pag","v8a-resist","v8a-peb","v8a-develop"],"prerequisiteIds":["a033-v8-23"],"title":"光阻材料評估","titleEn":"Deliver a resist assessment","objective":"完成「光阻材料評估」的工程驗收單，把PAG、淬熄、反應擴散與隨機性中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for deliver a resist assessment, connecting relevant limits in pag, quenching, reaction-diffusion and stochasticity to observable evidence.","instruction":"本步問題：光阻材料評估。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：需用相同曝光、顯影及蝕刻基準比較候選材料。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Deliver a resist assessment. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Compare candidate materials with matched exposure, development and etch baselines. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「需用相同曝光、顯影及蝕刻基準比較候選材料。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Compare candidate materials with matched exposure, development and etch baselines. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「光阻材料評估」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for deliver a resist assessment and add discriminating evidence.","check":"交付「光阻材料評估」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for deliver a resist assessment: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a033-v8-24-k1","title":"光阻材料評估的原理","titleEn":"Deliver a resist assessment principle","text":"需用相同曝光、顯影及蝕刻基準比較候選材料。","textEn":"Compare candidate materials with matched exposure, development and etch baselines."},{"id":"a033-v8-24-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","textEn":"Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}],"quiz":{"question":"評估「光阻材料評估」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating deliver a resist assessment?","options":["顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。","需用相同曝光、顯影及蝕刻基準比較候選材料。"],"optionsEn":["Developer compatibility follows directly from color.","More acid diffusion can only improve patterns.","Compare candidate materials with matched exposure, development and etch baselines."],"answer":2,"explanation":"需用相同曝光、顯影及蝕刻基準比較候選材料。 候選配方的解析度、粗糙度、感度及蝕刻耐受需在同一基準下比較，不能混用不同最佳條件宣稱全面勝出。","explanationEn":"Compare candidate materials with matched exposure, development and etch baselines. Compare resolution, roughness, sensitivity and etch resistance on the same baseline rather than mixing best conditions to claim universal superiority."}}]}],"subcategory":"lithography","subcategoryTitle":"光阻、光罩與微影","subcategoryTitleEn":"Resists, masks and lithography"}};
